// Build MQTT command payload
const command = {
    action: msg.payload,
    method: 'primary',  // Change based on your needs
    timestamp: new Date().toISOString(),
    request_id: `${msg.payload}-${Date.now()}`,
    source: 'dashboard',
    user: msg.req?.user?.username || 'system'
};

msg.payload = command;
msg.topic = 'MQTT_PREFIX/FEATURE/command/action1';

// Log the command
flow.set('lastCommand', {
    action: command.action,
    timestamp: command.timestamp
});

node.log(`ACTION1 command sent: ${JSON.stringify(command)}`);

return msg;

// Build MQTT command payload
const command = {
    action: msg.payload,
    method: 'secondary',
    timestamp: new Date().toISOString(),
    request_id: `${msg.payload}-${Date.now()}`,
    source: 'dashboard',
    user: msg.req?.user?.username || 'system'
};

msg.payload = command;
msg.topic = 'MQTT_PREFIX/FEATURE/command/action2';

flow.set('lastCommand', {
    action: command.action,
    timestamp: command.timestamp
});

node.log(`ACTION2 command sent: ${JSON.stringify(command)}`);

return msg;

// Build force command - requires confirmation
const command = {
    action: 'force_action',
    type: 'force',
    timestamp: new Date().toISOString(),
    request_id: `force-${Date.now()}`,
    source: 'dashboard',
    user: msg.req?.user?.username || 'system',
    confirmed: true
};

msg.payload = command;
msg.topic = 'MQTT_PREFIX/FEATURE/command/force';

flow.set('lastCommand', {
    action: command.action,
    timestamp: command.timestamp
});

node.warn(`FORCE command sent: ${JSON.stringify(command)}`);

return msg;

// Process command response
const response = msg.payload;

// Log response
if (response.success) {
    node.log(`Command successful: ${response.message}`);
} else {
    node.error(`Command failed: ${response.message}`);
}

// Update UI or trigger notifications
msg.notification = {
    type: response.success ? 'info' : 'error',
    message: response.message,
    timestamp: new Date().toISOString()
};

return msg;

// Log errors to system log
const error = {
    timestamp: new Date().toISOString(),
    level: 'ERROR',
    domain: 'DOMAIN',
    feature: 'FEATURE',
    message: msg.error?.message || 'Unknown error',
    stack: msg.error?.stack
};

node.error(JSON.stringify(error));

// Publish to system log topic
msg.payload = error;
msg.topic = 'system/logs';

return msg;
